    private static func screen(_ base64: String) -> String {
        String(decoding: Data(base64Encoded: base64) ?? Data(), as: UTF8.self)
    }

    static var questionOne: String { screen(questionOne64) }
    static var questionTwo: String { screen(questionTwo64) }
    static var notesOpen: String { screen(notesOpen64) }
    static var answered: String { screen(answered64) }
    #else
    static var questionOne: String { "" }
    static var questionTwo: String { "" }
    static var notesOpen: String { "" }
    static var answered: String { "" }
    #endif

    /// What codex shows after `keys` (or the note and its Enter) arrive.
    static func reaction(keys: [String], screen: String) -> String? {
        switch keys {
        case ["2"] where screen == questionOne: questionTwo
        case ["Down", "Down", "Tab"] where screen == questionTwo: notesOpen
        case ["Enter"] where screen == notesOpen: answered
        default: nil
        }
    }
}
